import { expect, expectStatus, test, type APIRequestContext } from "../../fixtures";

const TAG = "@LIF-01";

interface DocumentOut {
  id: string;
  vendor_id: string;
  kind: string;
  filename: string;
  status: string;
  created_at: string;
}

interface FieldOut {
  value: string | null;
  confidence: number;
}

interface ExtractionOut {
  id: string;
  document_id: string;
  kind: string;
  fields: Record<string, FieldOut>;
  status: string;
}

interface ReviewQueueItem {
  vendor_id: string;
  vendor_name: string;
  extractions: ExtractionOut[];
}

interface VendorOut {
  id: string;
  status: string;
}

/** Keeps names unique across parallel tests that share one database. */
function uniqueSuffix(): string {
  return `${Date.now().toString(36)}-${Math.random().toString(36).slice(2, 8)}`;
}

/** Document bytes whose text carries the legal name the extraction is expected to read. */
function w9File(legalName: string) {
  return {
    name: "w9.txt",
    mimeType: "text/plain",
    buffer: Buffer.from(`Form W-9\nLegal name: ${legalName}\n`),
  };
}

function otherFile(kind: string) {
  return {
    name: `${kind}.txt`,
    mimeType: "text/plain",
    buffer: Buffer.from(`Sample ${kind} document\n`),
  };
}

async function createDraftVendor(member: APIRequestContext, name: string): Promise<VendorOut> {
  const response = await member.post("/api/vendors", {
    data: {
      name,
      category: "services",
      contact_email: `ops-${uniqueSuffix()}@example.test`,
    },
  });
  return expectStatus<VendorOut>(response, 201);
}

async function uploadDocument(
  member: APIRequestContext,
  vendorId: string,
  kind: string,
  file: { name: string; mimeType: string; buffer: Buffer },
): Promise<DocumentOut> {
  const response = await member.post(`/api/vendors/${vendorId}/documents`, {
    multipart: { kind, file },
  });
  return expectStatus<DocumentOut>(response, 201);
}

/** Extraction runs after upload, so poll until the document reports it is extracted. */
async function awaitExtracted(member: APIRequestContext, documentId: string) {
  await expect
    .poll(
      async () => {
        const doc = await expectStatus<DocumentOut>(await member.get(`/api/documents/${documentId}`), 200);
        return doc.status;
      },
      { timeout: 30_000, intervals: [250, 500, 1000] },
    )
    .toBe("extracted");
}

test.describe("vendor lifecycle", () => {
  test(
    "a re-uploaded document is the one that gets reviewed",
    { tag: TAG },
    async ({ apiAs }) => {
      // Arrange: signed in as the member, with a draft vendor and its non-W-9 documents.
      const member = await apiAs("member");
      const vendor = await createDraftVendor(member, `Lifecycle Co ${uniqueSuffix()}`);

      const insurance = await uploadDocument(member, vendor.id, "insurance_certificate", otherFile("insurance_certificate"));
      const contract = await uploadDocument(member, vendor.id, "contract", otherFile("contract"));
      await awaitExtracted(member, insurance.id);
      await awaitExtracted(member, contract.id);

      // Arrange: two W-9 uploads, each extracted, with different legal names.
      const firstName = `First Name LLC ${uniqueSuffix()}`;
      const secondName = `Second Name LLC ${uniqueSuffix()}`;

      const firstW9 = await uploadDocument(member, vendor.id, "w9", w9File(firstName));
      await awaitExtracted(member, firstW9.id);

      const secondW9 = await uploadDocument(member, vendor.id, "w9", w9File(secondName));
      await awaitExtracted(member, secondW9.id);

      // Act: submit the vendor.
      const submitResponse = await member.post(`/api/vendors/${vendor.id}/submit`);
      const submitted = await expectStatus<VendorOut>(submitResponse, 200);
      expect(submitted.status).toBe("in_review");

      // Act: a reviewer opens the review queue.
      const reviewer = await apiAs("reviewer");
      const queueResponse = await reviewer.get("/api/review-queue");
      const queue = await expectStatus<ReviewQueueItem[]>(queueResponse, 200);

      // Assert: the vendor's W-9 extraction in the queue is the second upload's, with the second legal name.
      const item = queue.find((entry) => entry.vendor_id === vendor.id);
      expect(item, "submitted vendor should appear in the review queue").toBeDefined();

      const w9Extractions = item!.extractions.filter((e) => e.kind === "w9");
      expect(w9Extractions).toHaveLength(1);
      expect(w9Extractions[0].document_id).toBe(secondW9.id);
      expect(w9Extractions[0].fields["legal_name"]?.value).toBe(secondName);
      expect(w9Extractions.some((e) => e.document_id === firstW9.id)).toBe(false);

      // Assert: the vendor's documents list both W-9 uploads, oldest first.
      const listResponse = await member.get(`/api/vendors/${vendor.id}/documents`);
      const documents = await expectStatus<DocumentOut[]>(listResponse, 200);

      const w9Documents = documents.filter((d) => d.kind === "w9");
      expect(w9Documents.map((d) => d.id)).toEqual([firstW9.id, secondW9.id]);

      const createdTimes = w9Documents.map((d) => Date.parse(d.created_at));
      expect(createdTimes[0]).toBeLessThanOrEqual(createdTimes[1]);
    },
  );
});
